import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new ProblemSolver().solve(in, out);
        out.close();
    }

    static class ProblemSolver {
        int n, m, s;
        long t;

        void advance() {
            int jump = (int) ((t--) % n);
            int dir = (s < m) ? 1 : -1;
            s += dir * jump;
            if (s >= n || s < 0) {
                s %= n;
                if (s < 0) s += n;
            }
        }

        void batch() {
            int count = n;
            while (count-- > 0) advance();
        }

        void solve(InputReader in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            s = in.nextInt() - 1;
            t = in.nextLong();
            while (t % n != 0) advance();

            long[] seen = new long[n];
            for (int i = 0; i < n; i++) seen[i] = -1;
            while (t != 0) {
                batch();
                if (seen[s] != -1) {
                    long period = seen[s] - t;
                    t %= period;
                    break;
                }
                seen[s] = t;
            }
            while (t != 0) advance();
            out.println(s + 1);
        }
    }

    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        InputReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine(), " \t\n\r\f,");
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}
